extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var player_scene: PackedScene = load("res://player/player.tscn")
	if not check("player_scene", player_scene != null, "La scena res://player/player.tscn deve caricarsi correttamente"):
		return
	var player := player_scene.instantiate() as CharacterBody2D
	get_tree().root.add_child(player)
	await wait_frames(2)

	var jump_audio := player.get_node_or_null("JumpAudio") as AudioStreamPlayer2D
	if check("jump_audio", jump_audio != null, "Player deve avere il nodo JumpAudio"):
		if check("play_jump_sound", player.has_method("play_jump_sound"), "Player deve implementare play_jump_sound()"):
			player.play_jump_sound()
			check("pitch_jump", jump_audio.pitch_scale >= 0.89 and jump_audio.pitch_scale <= 1.11, "play_jump_sound() deve impostare pitch_scale tra 0.9 e 1.1 (trovato: %.2f)" % jump_audio.pitch_scale)

	var coin_scene: PackedScene = load("res://objects/coin.tscn")
	if check("coin_scene", coin_scene != null, "La scena res://objects/coin.tscn deve caricarsi"):
		var coin := coin_scene.instantiate() as Area2D
		get_tree().root.add_child(coin)
		await wait_frames(2)
		var coin_audio := coin.get_node_or_null("CoinAudio") as AudioStreamPlayer2D
		check("coin_audio", coin_audio != null, "Coin deve avere il nodo CoinAudio")
		coin.queue_free()
	player.queue_free()

