extends Area2D

@export var sparks_scene: PackedScene = preload("res://effects/coin_sparks.tscn")


func _ready() -> void:
	body_entered.connect(_on_body_entered)


func _on_body_entered(body: Node2D) -> void:
	if not body.is_in_group("player"):
		return

	if sparks_scene:
		var sparks := sparks_scene.instantiate() as GPUParticles2D
		sparks.global_position = global_position
		get_parent().add_child(sparks)

	var audio := get_node_or_null("CoinAudio") as AudioStreamPlayer2D
	if audio:
		audio.pitch_scale = randf_range(0.95, 1.25)
		audio.play()
		$Sprite2D.visible = false
		$CollisionShape2D.set_deferred("disabled", true)
		await audio.finished

	queue_free()

